def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Improved version of the equation for log10(|ID|/A) in OTFT p-channel Org4.
    Accounts for quadratic nature of current-voltage characteristic by including the square of both |VGS| and |VDS|."""

    a, b, c, d, e, f = parameters
    return a + b * gate_voltage_abs + c * drain_voltage_abs + d * (gate_voltage_abs ** 2) + e * (drain_voltage_abs ** 2)
